mapper.update:
UPDATE tbl_user
   SET name = #{name}
 WHERE id     = #{id}
   AND status = 'ACTIVE'

UPDATE tbl_user
   SET nickname = #{nickname}
 WHERE id     = #{id}
   AND status = 'ACTIVE'

mapper.select:
SELECT id
  FROM tbl_mission_difficulty
 WHERE difficulty_name = #{difficultyName}

mapper.update:
UPDATE tbl_user
   SET difficulty_id = #{difficultyId}
 WHERE id     = #{id}
   AND status = 'ACTIVE'

UPDATE tbl_user
   SET tutorial_seen_at = CASE WHEN #{target} = 'MAIN'
                               THEN #{seenAt,jdbcType=TIMESTAMP}
                               ELSE tutorial_seen_at END,
       group_tutorial_seen_at = CASE WHEN #{target} = 'GROUP'
                                     THEN #{seenAt,jdbcType=TIMESTAMP}
                                     ELSE group_tutorial_seen_at END
 WHERE id     = #{id}
   AND status = 'ACTIVE'

UPDATE tbl_user
   SET profile_image_key = #{profileImageKey}
 WHERE id     = #{id}
   AND status = 'ACTIVE'
